  const restoreImage=imageOpen,savedImageScale=imageScale,imageScroll=host.querySelector('.ft-image-scroll'),imagePosition=imageScroll?{top:imageScroll.scrollTop,left:imageScroll.scrollLeft}:null;imageOpen=false;
  updateFullscreen();let measured=size();host.innerHTML=renderHtml(d,s,measured,panels(),measureHeight);updateFullscreen();const actual=size();
  if(actual.width!==measured.width||actual.height!==measured.height){measured=actual;host.innerHTML=renderHtml(d,s,measured,panels(),measureHeight);updateFullscreen();}
