 function exitNativeFullscreen(){if(pendingNativeExits.length)return pendingNativeExits[0].promise||Promise.resolve();const transition={settled:false,eventSeen:false};pendingNativeExits.push(transition);const clear=()=>{pendingNativeExits=pendingNativeExits.filter(t=>t!==transition);};let exit;try{exit=doc.exitFullscreen();}catch{clear();reportExitFailure();return Promise.resolve();}transition.promise=Promise.resolve(exit).then(()=>{transition.settled=true;if(transition.eventSeen)clear();updateFullscreen();},()=>{clear();updateFullscreen();reportExitFailure();});return transition.promise;}
 function updateFullscreen(){const native=doc.fullscreenElement===host,mode=native?'浏览器全屏':'页内专注',b=$('ft-fullscreen');if(b){b.textContent=fullscreen?'退出'+mode:'专注 / 全屏';b.setAttribute('aria-pressed',String(fullscreen));}const status=$('ft-focus-status');if(status){status.hidden=!fullscreen;status.textContent=fullscreen?mode:'';}host.classList.toggle('ft-fullscreen',fullscreen);}
