 function showImage(scale=1){imageOpen=true;imageScale=scale;const which=s.tab==='a'?'analysis':'dual',im=SOURCE_IMAGES[which],el=$('ft-image-dialog');el.hidden=false;el.innerHTML='<section class="ft-image-modal" role="dialog" aria-modal="true" aria-labelledby="ft-image-title"><header><h2 id="ft-image-title">'+(which==='dual'?'原图：逆渲染双树':'原图：论文解析树')+'</h2>'+(im.data?button('image-minus','缩小')+button('image-plus','放大'):'')+button('image-close','关闭原图','id="ft-image-close"')+'</header>'+(im.data?'<p>完整原始像素 · '+im.width+' × '+im.height+' · 滚动查看全图，按钮缩放</p><div class="ft-image-scroll"><img id="ft-original-image" src="'+im.data+'" alt="'+(which==='dual'?'用户提供的完整双树原图':'用户提供的完整论文解析树原图')+'" style="width:'+(im.width*imageScale)+'px;max-width:none"></div>':'<p class="ft-warning">原图文件尚未恢复，当前无法查看完整像素。脑图保留此前逐图核对的节点与不确定标记；未以近似图片替代。此候选尚未完成原图查看验收。</p>')+'</section>';$('ft-viewport')?.setAttribute('inert','');$('ft-detail')?.setAttribute('inert','');$('ft-image-close')?.focus();}
 host.addEventListener('click',event=>{if(suppressClick){suppressClick=false;return;}const embedded=event.target.closest('[data-c2]');if(embedded){event.stopPropagation?.();if(embedded.dataset.c2==='gap'){commit({type:'detail-tab',tab:'unknown'},true,false);const q=host.querySelector('[data-question-id="'+embedded.dataset.id+'"]');q?.focus({preventScroll:true});if(q)$('ft-detail-body').scrollTop=q.offsetTop||0;}else if(['inspect','enter'].includes(embedded.dataset.c2))commit({type:'inspect',id:embedded.dataset.id});return;}const b=event.target.closest('[data-ft]');if(!b||b.disabled)return;const a=b.dataset.ft;event.stopPropagation?.();if(a==='fit'){fitView();return;}if(a==='fit-branch'){fitView(true);return;}if(a==='zoom-in'||a==='zoom-out'){const v=view(d,s),z=size();setCamera(zoom(v.camera,a==='zoom-in'?1.2:1/1.2,z.width/2,z.height/2));return;}if(a==='readable'){const g=getGraph(d,s),v=view(d,s),z=size();setCamera(readableCamera(g,v,scene(g,v,false,z.width,measureHeight),z.width,z.height));focusNode();return;}if(fullscreen&&(a==='details'||a==='minimap')){capture();if(a==='details')focusDetails=!focusDetails;else focusMinimap=!focusMinimap;render();$('ft-fullscreen')?.focus({preventScroll:true});return;}if(a==='fullscreen'){toggleFullscreen();return;}if(a==='image'){showImage();return;}if(a==='image-close'){closeImage();return;}if(a==='image-minus'||a==='image-plus'){const img=$('ft-original-image');if(!img)return;imageScale=Math.max(.15,Math.min(3,imageScale*(a==='image-plus'?1.25:.8)));img.style.width=SOURCE_IMAGES[s.tab==='a'?'analysis':'dual'].width*imageScale+'px';return;}if(a==='legacy'){capture();history();activate(false);win.history.pushState({},'',d.M.serialize(d.N.getState()));d.N.render();doc.querySelector('.masthead')?.focus?.();return;}commit({type:a,id:b.dataset.id,tab:b.dataset.tab,mode:b.dataset.mode,paper:b.dataset.paper,key:b.dataset.key});});
 host.addEventListener('change',event=>{if(event.target.id!=='ft-paper'||!event.target.value)return;const pid=event.target.value;if(s.tab==='a'){commit({type:'paper',paper:pid});return;}const paths=d.M.pathsForPaper(d.model,pid),path=paths.find(p=>p.key===s.tab)||paths[0];if(path)commit({type:'path',key:path.key,id:path.id});});
